class Solution {
public:
    int maxConsecutive(int bottom, int top, std::vector<int>& special) {
        std::sort(special.begin(), special.end());
        int ans = std::max(special[0] - bottom, top - special.back());
        for (int i = 1; i < (int)special.size(); ++i) {
            ans = std::max(ans, special[i] - special[i - 1] - 1);
        }
        return ans;
    }
};

class Solution {
    public int maxConsecutive(int bottom, int top, int[] special) {
        java.util.Arrays.sort(special);
        int ans = Math.max(special[0] - bottom, top - special[special.length - 1]);
        for (int i = 1; i < special.length; i++) {
            ans = Math.max(ans, special[i] - special[i - 1] - 1);
        }
        return ans;
    }
}

var maxConsecutive = function(bottom, top, special) {
    special.sort((a, b) => a - b);
    let ans = Math.max(special[0] - bottom, top - special[special.length - 1]);
    for (let i = 1; i < special.length; i++) {
        ans = Math.max(ans, special[i] - special[i - 1] - 1);
    }
    return ans;
};
